describe('Fachplanung Erstellung Dokumentation', () => {
  // Zielordner für diesen Workflow definieren
  Cypress.env('docu_target_dir', 'Funktionen/bilder/screenshots');

  it('R1 legt einen neuen Gesamtplan an (2027)', () => {
    cy.login('r1');
    cy.visit('/administration/it-gesamtplan');

    // Marginal-Menü: Neuen IT-Gesamtplan anlegen
    cy.get('a').contains('Neuen IT-Gesamtplan anlegen').click();

    // Formular ausfüllen
    cy.get('select[name="jahr_1"]').select('2027');
    cy.get('select[name="dauer"]').select('einjährig');

    cy.get('form[name="form-new-gesamtplan"]').first().docuScreenshot('01-gesamtplan-neu-formular');
    cy.get('input[name="btn-save"]').click();

    // Zurück in der Übersicht
    cy.get('h2').contains('2027').should('be.visible');
  });

  it('R1 initiiert die Fachplanungen für 2027', () => {
    cy.login('r1');
    cy.visit('/administration/it-gesamtplan');

    // Link "Neue IT-Fachplanungen anlegen" für 2027
    // Wir suchen das <h2> mit 2027 und dann die Liste danach
    cy.get('h2').contains('2027').parent().find('.th-lst-body').within(() => {
        cy.get('a').contains('Neue IT-Fachplanungen anlegen').click();
    });

    cy.get('main').docuScreenshot('02-fachplanungen-init-uebersicht');

    // Dienststellen auswählen (z.B. 9901)
    cy.get('input[type="checkbox"][id="fp-9901"]').check();

    cy.get('input[name="btn-save"]').first().invoke('removeAttr', 'disabled').click();
    cy.get('.alert-info').should('be.visible');
  });

  it('Erstelle einen Zweck mit der Nummer 123', () => {
    cy.login('r1');
    cy.visit('/administration/it-gesamtplan');
    // Neuen Zweck anlegen
    cy.get('h2').contains('2027').parent().next().find('.th-lst-body').within(() => {
      cy.get('a').contains('Haushaltstitel-Zweck-Liste bearbeiten').click();
    });

    // Neuen Zweck anlegen
    cy.get('a').contains('Neuen Zweck anlegen').click();

    // Formular ausfüllen
    cy.get('input[name="nummer"]').type('123');
    cy.get('input[name="name"]').type('Dokumentationstest');

    cy.docuScreenshot('03-zweck-neu-formular');

    cy.get('input[name="btn-save"]').click();
